use crate::{
    model::Message,
    reactions::{Summary, Update},
};
use libsql::{Connection, params};

pub(super) type Journal = super::journal::Journal<Update>;

pub(super) fn reconcile(journal: &Journal, message: &mut Message, started: i64) {
    for update in journal
        .since(started)
        .filter(|update| (update.chat, update.message) == (message.chat_id, message.id))
    {
        message
            .reactions
            .get_or_insert_with(Summary::default)
            .apply(&update.summary);
    }
    if journal.stale(started) {
        message.reactions.get_or_insert_with(Summary::default).stale = true;
    }
}

pub(super) fn reconcile_summary(
    journal: &Journal,
    chat: i64,
    id: i32,
    summary: &mut Summary,
    started: i64,
) {
    for update in journal
        .since(started)
        .filter(|update| (update.chat, update.message) == (chat, id))
    {
        summary.apply(&update.summary);
    }
    summary.stale |= journal.stale(started);
}

pub(super) async fn merge_cached(
    connection: &Connection,
    message: &mut Message,
) -> anyhow::Result<()> {
    if let Some(summary) = &mut message.reactions {
        merge_summary(connection, message.chat_id, message.id, summary).await?;
    }
    Ok(())
}

pub(super) async fn merge_summary(
    connection: &Connection,
    chat: i64,
    id: i32,
    fresh: &mut Summary,
) -> anyhow::Result<()> {
    if fresh.choices_known {
        return Ok(());
    }
    let row = connection
        .query(
            "SELECT data FROM messages WHERE chat_id=?1 AND id=?2 AND data IS NOT NULL",
            params![chat, id],
        )
        .await?
        .next()
        .await?;
    if let Some(row) = row {
        let cached: Message = serde_json::from_str(&row.get::<String>(0)?)?;
        if let Some(mut summary) = cached.reactions {
            summary.apply(fresh);
            *fresh = summary;
        }
    }
    Ok(())
}

pub(super) async fn apply(
    connection: &Connection,
    update: &Update,
    revision: i64,
) -> anyhow::Result<()> {
    let row = connection
        .query(
            "SELECT data FROM messages WHERE chat_id=?1 AND id=?2 AND data IS NOT NULL",
            params![update.chat, update.message],
        )
        .await?
        .next()
        .await?;
    if let Some(row) = row {
        let mut message: Message = serde_json::from_str(&row.get::<String>(0)?)?;
        message
            .reactions
            .get_or_insert_with(Summary::default)
            .apply(&update.summary);
        connection.execute("UPDATE messages SET data=?1,revision=?2 WHERE chat_id=?3 AND id=?4 AND data IS NOT NULL", params![serde_json::to_string(&message)?, revision, update.chat, update.message]).await?;
    }
    Ok(())
}

//! Merge a cloud snapshot with edits and tombstones received during its RPC.
use super::{NetworkEvent, Result, Store, params};

impl Store {
    pub(crate) async fn reconcile_cloud_search(&self, event: &mut NetworkEvent) -> Result<()> {
        let (request_id, chat_id, messages) = match event {
            NetworkEvent::CloudSearchResults {
                request_id,
                chat_id,
                page,
            } => (*request_id, *chat_id, &mut page.messages),
            NetworkEvent::CloudSearchContext {
                request_id,
                chat_id,
                messages,
                ..
            } => (*request_id, *chat_id, messages),
            _ => return Ok(()),
        };
        let Some((_, _, started)) = self
            .search_revision
            .filter(|(id, chat, _)| *id == request_id && *chat == chat_id)
        else {
            *event = NetworkEvent::SearchFailed {
                request_id,
                error: "History changed during search; run the search again".to_owned(),
            };
            return Ok(());
        };
        let mut merged = Vec::with_capacity(messages.len());
        for message in messages.drain(..) {
            if message.chat_id != chat_id || message.id <= 0 {
                continue;
            }
            if self
                .connection
                .query(
                    "SELECT 1 FROM global_deletions WHERE id=?1 AND ?2>-1000000000000",
                    params![message.id, chat_id],
                )
                .await?
                .next()
                .await?
                .is_some()
            {
                continue;
            }
            let row = self
                .connection
                .query(
                    "SELECT data,revision FROM messages WHERE chat_id=?1 AND id=?2",
                    params![chat_id, message.id],
                )
                .await?
                .next()
                .await?;
            if let Some(row) = row {
                let Some(data) = row.get::<Option<String>>(0)? else {
                    continue;
                };
                if row.get::<i64>(1)? > started {
                    merged.push(serde_json::from_str(&data)?);
                    continue;
                }
            }
            merged.push(message);
        }
        *messages = merged;
        Ok(())
    }
}

