//! Telegram reaction identity and partial-result semantics.
use crate::model::ChatId;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Eq, PartialEq, Ord, PartialOrd, Hash, Serialize, Deserialize)]
pub enum Kind {
    Emoji(String),
    Custom(i64),
    Paid,
}

impl Kind {
    #[must_use]
    pub fn label(&self) -> String {
        match self {
            Self::Emoji(emoji) => crate::model::sanitize_terminal_line(emoji),
            Self::Custom(_) => "[custom emoji]".to_owned(),
            Self::Paid => "★".to_owned(),
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub struct Count {
    pub kind: Kind,
    pub count: u32,
    pub chosen: Option<i32>,
}

#[derive(Clone, Debug, Default, Eq, PartialEq, Serialize, Deserialize)]
pub struct Summary {
    pub counts: Vec<Count>,
    pub choices_known: bool,
    pub as_tags: bool,
    pub stale: bool,
}

impl Summary {
    pub fn apply(&mut self, incoming: &Self) {
        let mut counts = incoming.counts.clone();
        if !incoming.choices_known {
            for count in &mut counts {
                count.chosen = self
                    .counts
                    .iter()
                    .find(|old| old.kind == count.kind)
                    .and_then(|old| old.chosen);
            }
        }
        self.counts = counts;
        self.as_tags = incoming.as_tags;
        self.stale = incoming.stale || (!incoming.choices_known && self.stale);
        self.choices_known |= incoming.choices_known;
    }

    #[must_use]
    pub fn chosen(&self) -> Vec<Kind> {
        let mut chosen: Vec<_> = self
            .counts
            .iter()
            .filter_map(|count| {
                (count.kind != Kind::Paid)
                    .then_some(count.chosen)
                    .flatten()
                    .map(|order| (order, count.kind.clone()))
            })
            .collect();
        chosen.sort_by_key(|(order, _)| *order);
        chosen.into_iter().map(|(_, kind)| kind).collect()
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Update {
    pub chat: ChatId,
    pub message: i32,
    pub summary: Summary,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Choice {
    pub emoji: String,
    pub title: String,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Review {
    pub summary: Summary,
    pub choices: Vec<Choice>,
    pub max_chosen: usize,
    pub max_unique: usize,
    pub read_only: Option<String>,
}

impl Review {
    /// Compute a fresh desired set, preserving the order and identity of other
    /// choices. Telegram replaces the oldest choice when the user's limit is hit.
    /// # Errors
    /// Rejects unavailable choices, unknown state and unique-reaction limits.
    pub fn toggle(&self, emoji: Option<&str>) -> Result<Vec<Kind>, String> {
        if let Some(reason) = &self.read_only {
            return Err(reason.clone());
        }
        if self.summary.stale || !self.summary.choices_known {
            return Err("Refresh reactions before changing them".to_owned());
        }
        let Some(emoji) = emoji else {
            return Ok(Vec::new());
        };
        let target = Kind::Emoji(emoji.to_owned());
        let mut chosen = self.summary.chosen();
        if chosen.contains(&target) {
            chosen.retain(|kind| *kind != target);
            return Ok(chosen);
        }
        if !self.choices.iter().any(|choice| choice.emoji == emoji) || self.max_chosen == 0 {
            return Err("This reaction is not available in this chat".to_owned());
        }
        while chosen.len() >= self.max_chosen {
            chosen.remove(0);
        }
        let unique = self
            .summary
            .counts
            .iter()
            .filter(|count| {
                count.kind != Kind::Paid
                    && count.count > 0
                    && !(count.count == 1
                        && count.chosen.is_some()
                        && !chosen.contains(&count.kind))
            })
            .count();
        if !self
            .summary
            .counts
            .iter()
            .any(|count| count.kind == target && count.count > 0)
            && unique >= self.max_unique
        {
            return Err("This message has reached its unique reaction limit".to_owned());
        }
        chosen.push(target);
        Ok(chosen)
    }
}

#[cfg(test)]
pub(crate) fn example() -> Review {
    Review {
        summary: Summary {
            counts: vec![
                Count {
                    kind: Kind::Emoji("👍".to_owned()),
                    count: 4,
                    chosen: Some(0),
                },
                Count {
                    kind: Kind::Custom(7),
                    count: 1,
                    chosen: Some(1),
                },
            ],
            choices_known: true,
            ..Summary::default()
        },
        choices: [("👍", "Like"), ("❤", "Love"), ("🔥", "Fire")]
            .into_iter()
            .map(|(emoji, title)| Choice {
                emoji: emoji.to_owned(),
                title: title.to_owned(),
            })
            .collect(),
        max_chosen: 3,
        max_unique: 11,
        read_only: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn minimal_reactions_keep_private_choices_but_drop_removed_counters() {
        let mut summary = example().summary;
        summary.apply(&Summary {
            counts: vec![Count {
                kind: Kind::Emoji("👍".to_owned()),
                count: 5,
                chosen: None,
            }],
            ..Summary::default()
        });
        assert_eq!(summary.chosen(), [Kind::Emoji("👍".to_owned())]);
        assert!(summary.choices_known);
        assert_eq!(summary.counts[0].count, 5);
        summary.apply(&Summary {
            choices_known: true,
            ..Summary::default()
        });
        assert!(summary.counts.is_empty());
    }

    #[test]
    fn changing_reactions_preserves_other_choices_and_telegram_limits() {
        let mut review = example();
        assert_eq!(review.toggle(Some("👍")).unwrap(), [Kind::Custom(7)]);
        assert_eq!(
            review.toggle(Some("❤")).unwrap(),
            [
                Kind::Emoji("👍".to_owned()),
                Kind::Custom(7),
                Kind::Emoji("❤".to_owned())
            ]
        );
        review.max_chosen = 2;
        assert_eq!(
            review.toggle(Some("❤")).unwrap(),
            [Kind::Custom(7), Kind::Emoji("❤".to_owned())]
        );
        review.max_unique = 2;
        assert!(
            review.toggle(Some("❤")).is_err(),
            "oldest choice still has other voters"
        );
        review.summary.counts[0].count = 1;
        assert!(
            review.toggle(Some("❤")).is_ok(),
            "replacing own exclusive choice frees a slot"
        );
        assert!(review.toggle(Some("unavailable")).is_err());
        assert!(review.toggle(None).unwrap().is_empty());
        review.summary.stale = true;
        assert!(review.toggle(None).is_err());
    }
}

use super::{ACCENT, MUTED, centered, pane_block, truncate_cells, wrap_cells};
use crate::{
    app::{AppState, MessageAction},
    model::Message,
    reactions::{Kind, Summary},
};
use ratatui::{
    Frame,
    layout::Rect,
    style::{Modifier, Style},
    text::{Line, Span},
    widgets::{Clear, Paragraph},
};

pub(super) fn transcript(message: &Message, width: usize) -> Vec<super::entities::Row> {
    let Some(summary) = &message.reactions else {
        return Vec::new();
    };
    let mut rows = Vec::new();
    let mut line = Line::default();
    for count in summary.counts.iter().filter(|count| count.count > 0) {
        let mine = count.chosen.is_some();
        let label = format!(
            "{}{} {}  ",
            if mine { "● " } else { "" },
            count.kind.label(),
            count.count
        );
        let label = truncate_cells(&label, width);
        let span = Span::styled(
            label,
            if mine {
                Style::default().fg(ACCENT).bold()
            } else {
                Style::default().fg(MUTED)
            },
        );
        if line.width() + span.width() > width && !line.spans.is_empty() {
            rows.push(super::entities::Row {
                line,
                action: Some(MessageAction::Reactions),
            });
            line = Line::default();
        }
        line.spans.push(span);
    }
    if !line.spans.is_empty() {
        rows.push(super::entities::Row {
            line,
            action: Some(MessageAction::Reactions),
        });
    }
    rows
}

pub(super) fn status(summary: &Summary) -> String {
    format!(
        "{} {}{}",
        summary
            .counts
            .iter()
            .map(|count| u64::from(count.count))
            .sum::<u64>(),
        if summary.as_tags { "tags" } else { "reactions" },
        if summary.stale { " · refreshing" } else { "" }
    )
}

pub(super) fn render(frame: &mut Frame<'_>, area: Rect, app: &mut AppState) {
    let Some(panel) = &mut app.reactions.panel else {
        return;
    };
    let popup = centered(
        area,
        area.width.saturating_sub(2).min(70),
        area.height.saturating_sub(2).min(24),
    );
    frame.render_widget(Clear, popup);
    let block = pane_block(
        format!(" Reactions · {} · #{} ", panel.title, panel.message),
        true,
    );
    let inner = block.inner(popup);
    frame.render_widget(block, popup);
    let notice = notice(panel);
    let width = usize::from(inner.width.max(1));
    let notice_height = inner
        .height
        .saturating_sub(2)
        .min(super::clamp_u16(wrap_cells(&notice, width).len()));
    frame.render_widget(
        Paragraph::new(
            wrap_cells(&notice, width)
                .into_iter()
                .map(|line| Line::styled(line, Style::default().fg(MUTED)))
                .collect::<Vec<_>>(),
        ),
        Rect {
            height: notice_height,
            ..inner
        },
    );
    let body = Rect {
        y: inner.y + notice_height,
        height: inner.height.saturating_sub(notice_height),
        ..inner
    };
    if panel.selected < panel.top {
        panel.top = panel.selected;
    }
    if panel.selected >= panel.top + usize::from(body.height) {
        panel.top = (panel.selected + 1).saturating_sub(usize::from(body.height));
    }
    app.reactions.hit_rows.clear();
    let lines: Vec<_> = panel
        .choices
        .iter()
        .enumerate()
        .skip(panel.top)
        .take(usize::from(body.height))
        .map(|(index, choice)| {
            let count = panel.review.as_ref().and_then(|review| {
                review
                    .summary
                    .counts
                    .iter()
                    .find(|count| count.kind == Kind::Emoji(choice.emoji.clone()))
            });
            let mine = count.is_some_and(|count| count.chosen.is_some());
            let label = format!(
                "{} {} · {}{}",
                if mine { "●" } else { "○" },
                crate::model::sanitize_terminal_line(&choice.emoji),
                choice.title,
                count.map_or_else(String::new, |count| format!(" · {}", count.count))
            );
            app.reactions.hit_rows.push((
                body.x,
                body.right(),
                body.y + super::clamp_u16(index - panel.top),
                index,
            ));
            let style = if mine {
                Style::default().fg(ACCENT).bold()
            } else {
                Style::default()
            };
            Line::styled(
                truncate_cells(&label, width),
                if index == panel.selected {
                    style.add_modifier(Modifier::REVERSED)
                } else {
                    style
                },
            )
        })
        .collect();
    frame.render_widget(Paragraph::new(lines), body);
}

fn notice(panel: &crate::app::reactions::Panel) -> String {
    panel.error.clone().unwrap_or_else(|| {
        if panel.loading.is_some() {
            "Loading available reactions…".to_owned()
        } else if panel.sending.is_some() {
            "Saving reactions…".to_owned()
        } else if let Some(review) = &panel.review {
            review.read_only.clone().unwrap_or_else(|| {
                if panel.choices.is_empty() {
                    "This chat has no available emoji reactions".to_owned()
                } else {
                    format!(
                        "{} per message · oldest choice is replaced at the limit",
                        review.max_chosen
                    )
                }
            })
        } else {
            "Refresh to load reactions".to_owned()
        }
    })
}

use crate::reactions::{Choice, Count, Kind, Review, Summary};
use anyhow::{Context, Result, ensure};
use grammers_client::{
    Client,
    message::{InputReactions, Message},
    tl,
};
use grammers_session::types::{PeerId, PeerKind, PeerRef};

fn kind(raw: &tl::enums::Reaction) -> Option<Kind> {
    match raw {
        tl::enums::Reaction::Emoji(value) => Some(Kind::Emoji(value.emoticon.clone())),
        tl::enums::Reaction::CustomEmoji(value) => Some(Kind::Custom(value.document_id)),
        tl::enums::Reaction::Paid => Some(Kind::Paid),
        tl::enums::Reaction::Empty => None,
    }
}

pub(super) fn summary(raw: &tl::enums::MessageReactions) -> Summary {
    let tl::enums::MessageReactions::Reactions(raw) = raw;
    Summary {
        counts: raw
            .results
            .iter()
            .filter_map(|count| {
                let tl::enums::ReactionCount::Count(count) = count;
                Some(Count {
                    kind: kind(&count.reaction)?,
                    count: u32::try_from(count.count).ok()?,
                    chosen: if raw.min { None } else { count.chosen_order },
                })
            })
            .collect(),
        choices_known: !raw.min,
        as_tags: raw.reactions_as_tags,
        stale: false,
    }
}

pub(super) fn map(message: &Message) -> Option<Summary> {
    match &message.raw {
        tl::enums::Message::Message(message) => message.reactions.as_ref().map(summary),
        tl::enums::Message::Service(message) => message.reactions.as_ref().map(summary),
        tl::enums::Message::Empty(_) => None,
    }
}

async fn own_choices(
    client: &Client,
    peer: PeerRef,
    id: i32,
    mut current: Summary,
) -> Result<Summary> {
    if current.choices_known {
        return Ok(current);
    }
    let updates = client
        .invoke(&tl::functions::messages::GetMessagesReactions {
            peer: peer.into(),
            id: vec![id],
        })
        .await?;
    let updates = match updates {
        tl::enums::Updates::Updates(updates) => updates.updates,
        tl::enums::Updates::Combined(updates) => updates.updates,
        tl::enums::Updates::UpdateShort(update) => vec![update.update],
        _ => Vec::new(),
    };
    for update in updates {
        if let tl::enums::Update::MessageReactions(update) = update
            && update.msg_id == id
            && PeerId::from(update.peer) == peer.id
        {
            current.apply(&summary(&update.reactions));
        }
    }
    ensure!(
        current.choices_known,
        "Telegram did not return your reaction choices; refresh"
    );
    Ok(current)
}

async fn allowed(
    client: &Client,
    peer: PeerRef,
) -> Result<(tl::enums::ChatReactions, Option<i32>)> {
    let full = match peer.id.kind() {
        PeerKind::User => {
            return Ok((
                tl::types::ChatReactionsAll { allow_custom: true }.into(),
                None,
            ));
        }
        PeerKind::Chat => {
            client
                .invoke(&tl::functions::messages::GetFullChat {
                    chat_id: peer.into(),
                })
                .await?
        }
        PeerKind::Channel => {
            client
                .invoke(&tl::functions::channels::GetFullChannel {
                    channel: peer.into(),
                })
                .await?
        }
    };
    let tl::enums::messages::ChatFull::Full(full) = full;
    let (reactions, limit) = match full.full_chat {
        tl::enums::ChatFull::Full(full) => (full.available_reactions, full.reactions_limit),
        tl::enums::ChatFull::ChannelFull(full) => (full.available_reactions, full.reactions_limit),
    };
    Ok((reactions.unwrap_or(tl::enums::ChatReactions::None), limit))
}

fn config_limit(config: &tl::enums::help::AppConfig, key: &str) -> Option<usize> {
    let tl::enums::help::AppConfig::Config(config) = config else {
        return None;
    };
    let tl::enums::Jsonvalue::JsonObject(object) = &config.config else {
        return None;
    };
    object.value.iter().find_map(|entry| {
        let tl::enums::JsonobjectValue::JsonObjectValue(entry) = entry;
        if entry.key != key {
            return None;
        }
        let tl::enums::Jsonvalue::JsonNumber(number) = &entry.value else {
            return None;
        };
        if !number.value.is_finite() || number.value.fract() != 0.0 {
            return None;
        }
        // Parse rather than truncating an unbounded floating-point value.
        number.value.to_string().parse().ok()
    })
}

pub(super) async fn review(
    client: &Client,
    peer: PeerRef,
    message_id: i32,
    self_id: i64,
) -> Result<Review> {
    let (message, me, available, config, (allowed, unique)) = tokio::try_join!(
        super::message_actions::fetch(client, peer, message_id),
        async { Ok::<_, anyhow::Error>(client.get_me().await?) },
        async {
            Ok::<_, anyhow::Error>(
                client
                    .invoke(&tl::functions::messages::GetAvailableReactions { hash: 0 })
                    .await?,
            )
        },
        async {
            Ok::<_, anyhow::Error>(
                client
                    .invoke(&tl::functions::help::GetAppConfig { hash: 0 })
                    .await?,
            )
        },
        allowed(client, peer),
    )?;
    let possible = match &message.raw {
        tl::enums::Message::Message(_) => true,
        tl::enums::Message::Service(message) => message.reactions_are_possible,
        tl::enums::Message::Empty(_) => false,
    };
    let summary = map(&message).unwrap_or(Summary {
        choices_known: true,
        ..Summary::default()
    });
    let summary = own_choices(client, peer, message_id, summary).await?;
    let premium = matches!(me.raw, tl::enums::User::User(user) if user.premium);
    let max_chosen = config_limit(
        &config,
        if premium {
            "reactions_user_max_premium"
        } else {
            "reactions_user_max_default"
        },
    )
    .unwrap_or(if premium { 3 } else { 1 });
    let max_unique = unique
        .and_then(|n| usize::try_from(n).ok())
        .or_else(|| config_limit(&config, "reactions_uniq_max"))
        .unwrap_or(usize::MAX);
    let tl::enums::messages::AvailableReactions::Reactions(available) = available else {
        anyhow::bail!("Telegram did not return available reactions; refresh");
    };
    let choices = available
        .reactions
        .into_iter()
        .filter_map(|reaction| {
            let tl::enums::AvailableReaction::Reaction(reaction) = reaction;
            let permitted = match &allowed {
                tl::enums::ChatReactions::None => false,
                tl::enums::ChatReactions::All(_) => true,
                tl::enums::ChatReactions::Some(allowed) => allowed
                    .reactions
                    .iter()
                    .any(|item| kind(item) == Some(Kind::Emoji(reaction.reaction.clone()))),
            };
            (permitted && !reaction.inactive && (!reaction.premium || premium)).then(|| Choice {
                emoji: reaction.reaction,
                title: crate::model::sanitize_terminal_line(&reaction.title),
            })
        })
        .collect();
    let read_only = if peer.id == PeerId::user_unchecked(self_id) || summary.as_tags {
        Some("Saved Messages use tags; manage them in an official client".to_owned())
    } else if !possible {
        Some("This service message does not accept reactions".to_owned())
    } else {
        None
    };
    Ok(Review {
        summary,
        choices,
        max_chosen,
        max_unique,
        read_only,
    })
}

pub(super) async fn change(
    client: &Client,
    peer: PeerRef,
    message_id: i32,
    self_id: i64,
    expected: &[Kind],
    emoji: Option<&str>,
) -> Result<()> {
    let latest = review(client, peer, message_id, self_id).await?;
    ensure!(
        latest.summary.chosen() == expected,
        "Your reactions changed in another client; refresh before retrying"
    );
    let desired = latest.toggle(emoji).map_err(anyhow::Error::msg)?;
    let reactions: Vec<tl::enums::Reaction> = desired
        .into_iter()
        .filter_map(|kind| match kind {
            Kind::Emoji(emoticon) => Some(tl::types::ReactionEmoji { emoticon }.into()),
            Kind::Custom(document_id) => {
                Some(tl::types::ReactionCustomEmoji { document_id }.into())
            }
            Kind::Paid => None,
        })
        .collect();
    client
        .send_reactions(
            peer,
            message_id,
            InputReactions::from(reactions).add_to_recent(),
        )
        .await
        .context("Could not change reactions")?;
    Ok(())
}

pub(super) async fn refresh(client: &Client, peer: PeerRef, ids: Vec<i32>) -> Result<()> {
    client
        .invoke(&tl::functions::messages::GetMessagesReactions {
            peer: peer.into(),
            id: ids,
        })
        .await?;
    Ok(())
}

//! Exact-peer snapshot checks shared by destructive message operations.
use anyhow::{Context, Result, ensure};
use grammers_client::{
    Client,
    message::Message,
    tl::{self, Serializable},
};
use grammers_session::types::PeerRef;
use sha2::{Digest, Sha256};

pub(super) async fn fetch(client: &Client, peer: PeerRef, id: i32) -> Result<Message> {
    ensure!(id > 0, "Select a delivered message");
    let message = client
        .get_messages_by_id(peer, &[id])
        .await?
        .pop()
        .flatten()
        .context("Message is no longer available")?;
    // messages.getMessages/deleteMessages do not accept a peer on non-channel
    // chats. Checking only the caller's supplied chat would be insufficient.
    ensure!(
        message.peer_id() == peer.id,
        "Message does not belong to the selected chat"
    );
    Ok(message)
}

pub(super) fn revision(message: &Message) -> [u8; 32] {
    let mut hash = Sha256::new();
    hash.update(message.text().as_bytes());
    hash.update(
        message
            .edit_date()
            .map_or(0, |date| date.timestamp())
            .to_le_bytes(),
    );
    for entity in message.fmt_entities().into_iter().flatten() {
        hash.update(entity.to_bytes());
    }
    if let tl::enums::Message::Message(raw) = &message.raw {
        let media_id = match &raw.media {
            Some(tl::enums::MessageMedia::Photo(media)) => match &media.photo {
                Some(tl::enums::Photo::Photo(photo)) => photo.id,
                _ => 0,
            },
            Some(tl::enums::MessageMedia::Document(media)) => match &media.document {
                Some(tl::enums::Document::Document(document)) => document.id,
                _ => 0,
            },
            Some(tl::enums::MessageMedia::Poll(media)) => {
                // Poll choices may change independently of the text. Counts
                // intentionally do not invalidate a reviewed message action.
                hash.update(media.poll.to_bytes());
                0
            }
            _ => 0,
        };
        hash.update(media_id.to_le_bytes());
    }
    hash.finalize().into()
}

use super::{App, Focus, Mode, Screen};
use crate::{
    actions::Action,
    event::{ConnectionStatus, NetworkEvent, TelegramCommand},
    model::ChatId,
    reactions::{Choice, Kind, Review, Summary, Update},
};
use std::time::{Duration, Instant};

#[derive(Clone, Default)]
pub struct State {
    pub panel: Option<Panel>,
    pub hit_rows: Vec<(u16, u16, u16, usize)>,
    visible: Vec<(ChatId, i32)>,
    refreshed: Vec<(ChatId, i32)>,
    refresh: Option<(ChatId, u64)>,
    due: Option<Instant>,
    next: u64,
}

#[derive(Clone)]
pub struct Panel {
    pub chat: ChatId,
    pub message: i32,
    pub title: String,
    pub review: Option<Review>,
    pub selected: usize,
    pub choices: Vec<Choice>,
    pub top: usize,
    pub loading: Option<u64>,
    pub sending: Option<u64>,
    pub ready: bool,
    pub error: Option<String>,
}

impl Panel {
    fn loaded(&mut self, review: Review) {
        self.choices.clone_from(&review.choices);
        for kind in review.summary.chosen() {
            if let Kind::Emoji(emoji) = kind
                && !self.choices.iter().any(|choice| choice.emoji == emoji)
            {
                self.choices.push(Choice {
                    emoji,
                    title: "Selected · remove only".to_owned(),
                });
            }
        }
        self.ready = !review.summary.stale && review.summary.choices_known;
        self.selected = self.selected.min(self.choices.len().saturating_sub(1));
        self.review = Some(review);
        self.error = None;
    }
}

impl App {
    fn next_reaction_request(&mut self) -> u64 {
        self.reactions.next = self.reactions.next.wrapping_add(1).max(1);
        self.reactions.next
    }

    pub(super) fn begin_reactions(&mut self) -> Vec<TelegramCommand> {
        if self.screen != Screen::Main
            || self.mode != Mode::Navigate
            || self.focus != Focus::Conversation
        {
            return Vec::new();
        }
        if self
            .reactions
            .panel
            .as_ref()
            .is_some_and(|panel| panel.sending.is_some())
        {
            self.status_message = Some("Wait for the pending reaction to finish".to_owned());
            return Vec::new();
        }
        let Some(message) = self.inspected_message().filter(|message| message.id > 0) else {
            return Vec::new();
        };
        self.reactions.panel = Some(Panel {
            chat: message.chat_id,
            message: message.id,
            title: self
                .active_chat()
                .map_or_else(|| "Reactions".to_owned(), |chat| chat.title.clone()),
            review: None,
            choices: Vec::new(),
            selected: 0,
            top: 0,
            loading: None,
            sending: None,
            ready: false,
            error: None,
        });
        self.mode = Mode::Reactions;
        self.status_message = None;
        self.load_reactions()
    }

    fn load_reactions(&mut self) -> Vec<TelegramCommand> {
        let request_id = self.next_reaction_request();
        let Some(panel) = &mut self.reactions.panel else {
            return Vec::new();
        };
        if panel.loading.is_some() || panel.sending.is_some() {
            return Vec::new();
        }
        panel.ready = false;
        if self.connection != ConnectionStatus::Online {
            panel.error = Some("Connect to Telegram to choose reactions".to_owned());
            return Vec::new();
        }
        panel.loading = Some(request_id);
        panel.error = None;
        vec![TelegramCommand::LoadReactions {
            chat_id: panel.chat,
            message_id: panel.message,
            request_id,
        }]
    }

    pub(super) fn reaction_binding(
        &mut self,
        action: &Action,
        count: usize,
    ) -> Option<Vec<TelegramCommand>> {
        if *action == Action::Reactions {
            return Some(self.begin_reactions());
        }
        if self.mode != Mode::Reactions {
            return None;
        }
        let mut commands = Vec::new();
        match action {
            Action::Cancel => {
                self.mode = Mode::Navigate;
                if self
                    .reactions
                    .panel
                    .as_ref()
                    .is_none_or(|panel| panel.sending.is_none())
                {
                    self.reactions.panel = None;
                }
            }
            Action::Refresh => commands = self.load_reactions(),
            Action::Open | Action::Send => commands = self.change_reaction(false),
            Action::ClearReactions => commands = self.change_reaction(true),
            Action::Up
            | Action::Down
            | Action::PageUp
            | Action::PageDown
            | Action::Home
            | Action::End => {
                if let Some(panel) = &mut self.reactions.panel {
                    let step = if matches!(action, Action::PageUp | Action::PageDown) {
                        count.saturating_mul(10)
                    } else {
                        count
                    };
                    panel.selected = match action {
                        Action::Up | Action::PageUp => panel.selected.saturating_sub(step),
                        Action::Home => 0,
                        Action::End => panel.choices.len().saturating_sub(1),
                        _ => panel
                            .selected
                            .saturating_add(step)
                            .min(panel.choices.len().saturating_sub(1)),
                    };
                }
            }
            Action::Quit | Action::Redraw => return None,
            _ => {}
        }
        Some(commands)
    }

    fn change_reaction(&mut self, clear: bool) -> Vec<TelegramCommand> {
        let request_id = self.next_reaction_request();
        let Some(panel) = &mut self.reactions.panel else {
            return Vec::new();
        };
        if !panel.ready || panel.loading.is_some() || panel.sending.is_some() {
            return Vec::new();
        }
        if self.connection != ConnectionStatus::Online {
            panel.error = Some("Connect to Telegram before changing reactions".to_owned());
            return Vec::new();
        }
        let Some(review) = &panel.review else {
            return Vec::new();
        };
        let emoji = if clear {
            None
        } else {
            let Some(choice) = panel.choices.get(panel.selected) else {
                return Vec::new();
            };
            Some(choice.emoji.clone())
        };
        if let Err(error) = review.toggle(emoji.as_deref()) {
            panel.error = Some(error);
            return Vec::new();
        }
        let expected = review.summary.chosen();
        if clear && expected.is_empty() {
            return Vec::new();
        }
        panel.sending = Some(request_id);
        panel.error = None;
        vec![TelegramCommand::ChangeReaction {
            chat_id: panel.chat,
            message_id: panel.message,
            request_id,
            expected,
            emoji,
        }]
    }

    fn apply_reactions(&mut self, update: &Update) {
        self.visit_messages(|message| {
            if (message.chat_id, message.id) == (update.chat, update.message) {
                message
                    .reactions
                    .get_or_insert_with(Summary::default)
                    .apply(&update.summary);
            }
        });
        if let Some(panel) = &mut self.reactions.panel
            && (panel.chat, panel.message) == (update.chat, update.message)
            && let Some(review) = &mut panel.review
        {
            review.summary.apply(&update.summary);
        }
    }

    #[allow(clippy::too_many_lines)]
    pub(super) fn observe_reactions(
        &mut self,
        event: &NetworkEvent,
    ) -> Option<Vec<TelegramCommand>> {
        match event {
            NetworkEvent::ReactionsChanged(update) => {
                self.apply_reactions(update);
                return Some(Vec::new());
            }
            NetworkEvent::ReactionsLoading { .. } => return Some(Vec::new()),
            NetworkEvent::ReactionsLoaded {
                chat_id,
                message_id,
                request_id,
                result,
            } => {
                if let Ok(review) = result {
                    self.apply_reactions(&Update {
                        chat: *chat_id,
                        message: *message_id,
                        summary: review.summary.clone(),
                    });
                }
                if let Some(panel) = &mut self.reactions.panel
                    && panel.loading == Some(*request_id)
                    && (panel.chat, panel.message) == (*chat_id, *message_id)
                {
                    panel.loading = None;
                    match result {
                        Ok(review) => panel.loaded(review.clone()),
                        Err(error) => {
                            panel.error = Some(crate::model::sanitize_terminal_line(error));
                        }
                    }
                }
                return Some(Vec::new());
            }
            NetworkEvent::ReactionsFinished {
                chat_id,
                message_id,
                request_id,
                error,
            } => {
                if message_id.is_none() && self.reactions.refresh == Some((*chat_id, *request_id)) {
                    self.reactions.refresh = None;
                    self.reactions.due = Some(Instant::now() + Duration::from_secs(30));
                }
                if let Some(panel) = &mut self.reactions.panel
                    && panel.sending == Some(*request_id)
                    && panel.chat == *chat_id
                    && Some(panel.message) == *message_id
                {
                    panel.sending = None;
                    panel.ready = false;
                    if let Some(error) = error {
                        panel.error = Some(format!(
                            "{} · refresh before retrying",
                            crate::model::sanitize_terminal_line(error)
                        ));
                        if self.mode != Mode::Reactions {
                            self.status_message.clone_from(&panel.error);
                        }
                    } else if self.mode == Mode::Reactions {
                        return Some(self.load_reactions());
                    } else {
                        self.reactions.panel = None;
                        self.status_message = Some("Reactions saved".to_owned());
                    }
                }
                return Some(Vec::new());
            }
            NetworkEvent::MessageUpdated(message) => {
                if let Some(summary) = &message.reactions {
                    self.apply_reactions(&Update {
                        chat: message.chat_id,
                        message: message.id,
                        summary: summary.clone(),
                    });
                }
            }
            NetworkEvent::MessagesDeleted {
                channel_id,
                message_ids,
            } => {
                if let Some(panel) = &mut self.reactions.panel
                    && channel_id.map_or(panel.chat > -1_000_000_000_000, |chat| chat == panel.chat)
                    && message_ids.contains(&panel.message)
                {
                    panel.ready = false;
                    panel.loading = None;
                    panel.error = Some("This message was deleted".to_owned());
                }
            }
            NetworkEvent::CacheInvalidated { chat_id } => {
                if let Some(panel) = &mut self.reactions.panel
                    && chat_id.is_none_or(|chat| chat == panel.chat)
                {
                    panel.ready = false;
                    panel.loading = None;
                    panel.error = Some("History changed; reopen reactions".to_owned());
                }
            }
            _ => {}
        }
        None
    }

    pub fn set_visible_reactions(&mut self, ids: Vec<(ChatId, i32)>) {
        self.reactions.visible = ids;
    }

    fn reactions_visible(&self) -> bool {
        self.screen == Screen::Main
            && self.terminal_focused
            && self.connection == ConnectionStatus::Online
            && matches!(self.mode, Mode::Navigate | Mode::Compose | Mode::Reactions)
            && !self.reactions.visible.is_empty()
    }

    pub fn request_visible_reactions(&mut self) -> Vec<TelegramCommand> {
        if !self.reactions_visible()
            || self.reactions.refresh.is_some()
            || (self.reactions.refreshed == self.reactions.visible
                && self.reactions.due.is_none_or(|due| due > Instant::now()))
            || self
                .reactions
                .panel
                .as_ref()
                .is_some_and(|panel| panel.loading.is_some() || panel.sending.is_some())
        {
            return Vec::new();
        }
        let Some(chat_id) = self.active_chat_id else {
            return Vec::new();
        };
        let message_ids: Vec<_> = self
            .reactions
            .visible
            .iter()
            .filter(|(chat, _)| *chat == chat_id)
            .map(|(_, id)| *id)
            .take(100)
            .collect();
        if message_ids.is_empty() {
            return Vec::new();
        }
        let request_id = self.next_reaction_request();
        self.reactions.refresh = Some((chat_id, request_id));
        self.reactions.refreshed.clone_from(&self.reactions.visible);
        vec![TelegramCommand::RefreshReactions {
            chat_id,
            message_ids,
            request_id,
        }]
    }

    #[must_use]
    pub fn next_reaction_deadline(&self) -> Option<Instant> {
        if !self.reactions_visible()
            || self.reactions.refresh.is_some()
            || self
                .reactions
                .panel
                .as_ref()
                .is_some_and(|panel| panel.loading.is_some() || panel.sending.is_some())
        {
            return None;
        }
        if self.reactions.refreshed == self.reactions.visible {
            self.reactions.due
        } else {
            Some(Instant::now())
        }
    }
}

use serde::{Deserialize, Serialize};

use chrono::{DateTime, Local, TimeZone, Utc};
use std::path::Path;

pub type ChatId = i64;

#[derive(Serialize, Deserialize, Clone, Debug, Eq, PartialEq)]
pub struct Chat {
    pub id: ChatId,
    pub title: String,
    pub kind: ChatKind,
    #[serde(default)]
    pub membership: crate::folders::ChatMembership,
    pub unread: u32,
    /// None means an older cache without a server read boundary.
    #[serde(default)]
    pub read_inbox_max_id: Option<i32>,
    pub last_message: String,
    #[serde(default)]
    pub last_message_id: Option<i32>,
    pub last_activity: Option<DateTime<Utc>>,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, Eq, PartialEq)]
pub enum ChatKind {
    Direct,
    Group,
    Channel,
}

/// Downloadable media attached to a Telegram message.
///
/// This deliberately contains metadata only. Telegram's file reference stays
/// in the network layer and is refreshed on demand before a download.
#[derive(Serialize, Deserialize, Clone, Debug, Eq, PartialEq)]
pub struct Attachment {
    #[serde(default)]
    pub source_id: Option<i64>,
    pub kind: AttachmentKind,
    pub file_name: Option<String>,
    pub mime_type: Option<String>,
    pub size: Option<u64>,
    /// Unicode fallback supplied by Telegram for stickers.
    pub fallback_emoji: Option<String>,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, Eq, PartialEq)]
pub enum AttachmentKind {
    Photo,
    File,
    Video,
    Audio,
    Sticker,
    Other,
}

impl Attachment {
    /// Media that can be shown in the terminal without opening an external app.
    #[must_use]
    pub fn supports_preview(&self) -> bool {
        matches!(self.kind, AttachmentKind::Photo | AttachmentKind::Sticker)
            || self
                .mime_type
                .as_deref()
                .is_some_and(|mime| mime.starts_with("image/"))
    }

    /// Telegram supplies raster thumbnails for animated/vector stickers.
    #[must_use]
    pub fn preview_uses_thumbnail(&self) -> bool {
        self.kind == AttachmentKind::Sticker
            && matches!(
                self.mime_type.as_deref(),
                Some("application/x-tgsticker" | "video/webm")
            )
    }

    /// A safe display name and download-file hint.
    #[must_use]
    pub fn display_name(&self) -> &str {
        self.file_name.as_deref().unwrap_or(match self.kind {
            AttachmentKind::Photo => "photo.jpg",
            AttachmentKind::File | AttachmentKind::Other => "attachment",
            AttachmentKind::Video => "video",
            AttachmentKind::Audio => "audio",
            AttachmentKind::Sticker => "sticker",
        })
    }

    /// Infer whether a dragged file should be sent as a compressed photo.
    #[must_use]
    pub fn path_looks_like_photo(path: &Path) -> bool {
        path.extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| {
                matches!(
                    extension.to_ascii_lowercase().as_str(),
                    "jpg" | "jpeg" | "png" | "webp"
                )
            })
    }
}

#[derive(Serialize, Deserialize, Clone, Debug, Eq, PartialEq)]
pub struct Mention {
    pub unread: bool,
    /// Voice, round-video or self-destructing content needs explicit consumption.
    pub requires_playback: bool,
}

/// A sendable sticker reference. File references expire after some days, so
/// panels revalidate the cached lists against Telegram and a failed send
/// retries once with a fresh reference instead of persisting them.
#[derive(Serialize, Deserialize, Clone, Debug, Eq, PartialEq)]
pub struct StickerRef {
    pub id: i64,
    pub access_hash: i64,
    pub file_reference: Vec<u8>,
    pub emoji: String,
    pub mime_type: String,
