//! Bounded, cancellable regex searches over the account's local message cache.
use crate::{
    event::NetworkEvent,
    model::{ChatId, Message},
};
use anyhow::{Result, bail};
use libsql::{OpenFlags, params};
use std::{
    collections::HashSet,
    path::{Path, PathBuf},
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    time::Duration,
};

const PAGE_SIZE: usize = 100;
const SCAN_BATCH: i64 = 128;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Cursor(pub i64, pub ChatId, pub i32);

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Request {
    pub id: u64,
    pub pattern: String,
    /// None means all cached conversations; Some(empty) is an empty scope.
    pub chats: Option<Vec<ChatId>>,
    pub before: Option<Cursor>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Page {
    pub messages: Vec<Message>,
    pub next: Option<Cursor>,
    pub cached_messages: usize,
    pub oldest: Option<i64>,
    pub newest: Option<i64>,
}

pub(crate) struct Worker {
    path: PathBuf,
    jobs: tokio::task::JoinSet<(u64, Arc<AtomicBool>, Result<Page>)>,
    cancel: Arc<AtomicBool>,
    pending: Option<Request>,
}

impl Worker {
    pub fn new(path: PathBuf) -> Self {
        Self {
            path,
            jobs: tokio::task::JoinSet::new(),
            cancel: Arc::default(),
            pending: None,
        }
    }
    pub fn queue(&mut self, request: Request) {
        self.cancel();
        self.pending = Some(request);
    }
    pub fn cancel(&mut self) {
        self.cancel.store(true, Ordering::Relaxed);
        self.pending = None;
    }
    pub fn start_pending(&mut self) {
        if !self.jobs.is_empty() {
            return;
        }
        let Some(request) = self.pending.take() else {
            return;
        };
        self.cancel = Arc::default();
        let cancel = self.cancel.clone();
        let path = self.path.clone();
        let runtime = tokio::runtime::Handle::current();
        self.jobs.spawn_blocking(move || {
            let result = runtime.block_on(scan(&path, &request, &cancel));
            (request.id, cancel, result)
        });
    }
    pub fn running(&self) -> bool {
        !self.jobs.is_empty()
    }
    pub async fn next(&mut self) -> Option<NetworkEvent> {
        match self.jobs.join_next().await? {
            Ok((_, cancel, _)) if cancel.load(Ordering::Relaxed) => None,
            Ok((request_id, _, Ok(page))) => Some(NetworkEvent::SearchResults { request_id, page }),
            Ok((request_id, _, Err(error))) => Some(NetworkEvent::SearchFailed {
                request_id,
                error: format!("{error:#}"),
            }),
            Err(error) => Some(NetworkEvent::Error(format!(
                "Local search task failed: {error}"
            ))),
        }
    }
}

impl Drop for Worker {
    fn drop(&mut self) {
        self.cancel();
    }
}

async fn scan(path: &Path, request: &Request, cancel: &AtomicBool) -> Result<Page> {
    if request.pattern.len() > 4096 {
        bail!("Regular expression is longer than 4096 bytes");
    }
    let regex = regex::RegexBuilder::new(&request.pattern)
        .size_limit(4 * 1024 * 1024)
        .dfa_size_limit(2 * 1024 * 1024)
        .build()?;
    let database = libsql::Builder::new_local(path)
        .flags(OpenFlags::SQLITE_OPEN_READ_ONLY)
        .build()
        .await?;
    let connection = database.connect()?;
    connection.busy_timeout(Duration::from_millis(250))?;
    let scope = request
        .chats
        .as_ref()
        .map(|ids| ids.iter().copied().collect::<HashSet<_>>());
    let mut page = Page {
        messages: Vec::new(),
        next: None,
        cached_messages: 0,
        oldest: None,
        newest: None,
    };
    let mut cursor = Cursor(i64::MAX, i64::MAX, i32::MAX);
    let mut last_match = None;
    let mut full = false;
    loop {
        if cancel.load(Ordering::Relaxed) {
            bail!("Search cancelled");
        }
        let mut rows = connection.query(
            "SELECT m.timestamp,m.chat_id,m.id,m.data FROM messages m JOIN chats c ON c.id=m.chat_id WHERE m.data IS NOT NULL AND (m.timestamp,m.chat_id,m.id)<(?1,?2,?3) ORDER BY m.timestamp DESC,m.chat_id DESC,m.id DESC LIMIT ?4",
            params![cursor.0, cursor.1, cursor.2, SCAN_BATCH]).await?;
        let mut scanned = 0;
        while let Some(row) = rows.next().await? {
            if cancel.load(Ordering::Relaxed) {
                bail!("Search cancelled");
            }
            cursor = Cursor(row.get(0)?, row.get(1)?, row.get(2)?);
            scanned += 1;
            if scope.as_ref().is_some_and(|ids| !ids.contains(&cursor.1)) {
                continue;
            }
            page.cached_messages += 1;
            page.oldest = Some(cursor.0);
            page.newest.get_or_insert(cursor.0);
            if full
                || request.before.is_some_and(|before| {
                    (cursor.0, cursor.1, cursor.2) >= (before.0, before.1, before.2)
                })
            {
                continue;
            }
            let message: Message = serde_json::from_str(&row.get::<String>(3)?)?;
            if regex.is_match(&message.text) {
                if page.messages.len() == PAGE_SIZE {
                    page.next = last_match;
                    full = true;
                } else {
                    page.messages.push(message);
                    last_match = Some(cursor);
                }
            }
        }
        if scanned < SCAN_BATCH {
            break;
        }
    }
    Ok(page)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        cache::Store,
        model::{Chat, ChatKind, Delivery},
    };
    use chrono::TimeZone;

    #[tokio::test]
    async fn regex_search_pages_scopes_tombstones_and_stale_context() {
        let dir = std::env::temp_dir().join(format!("termgram-search-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("cache.sqlite3");
        let mut store = Store::open(&path).await.unwrap();
        let chat = |id| Chat {
            id,
            title: format!("Chat {id}"),
            kind: ChatKind::Group,
            unread: 0,
            last_message_id: None,
            last_message: String::new(),
            last_activity: None,
            read_inbox_max_id: Some(0),
            membership: crate::folders::ChatMembership::default(),
        };
        let mut events = vec![NetworkEvent::Dialogs(vec![chat(42), chat(43)])];
        for id in 1..=206 {
            events.push(NetworkEvent::NewMessage(Message {
                reactions: None,
                poll: None,
                entities: Vec::new(),
                notification: None,
                mention: None,
                edited_at: None,
                pinned: false,
                id,
                chat_id: if id == 206 { 43 } else { 42 },
                sender_username: None,
                sender: "Ada".to_owned(),
                reply_to: None,
                text: format!("東京 error {id}"),
                timestamp: chrono::Utc.timestamp_opt(i64::from(id), 0).unwrap(),
                outgoing: false,
                delivery: Delivery::Read,
                attachment: None,
                links: Vec::new(),
                buttons: Vec::new(),
            }));
        }
        events.push(NetworkEvent::MessagesDeleted {
            channel_id: None,
            message_ids: vec![11],
        });
        store.apply(&events).await.unwrap();
        let mut request = Request {
            id: 1,
            pattern: r"東京.*error \d+$".to_owned(),
            chats: Some(vec![42]),
            before: None,
        };
        let cancelled = AtomicBool::new(false);
        let first = scan(&path, &request, &cancelled).await.unwrap();
        assert_eq!(first.cached_messages, 204);
        assert_eq!(first.messages.len(), 100);
        assert_eq!(first.messages[0].id, 205);
        request.before = first.next;
        let second = scan(&path, &request, &cancelled).await.unwrap();
        assert_eq!(second.messages.len(), 100);
        assert!(
            second
                .messages
                .iter()
                .all(|message| !first.messages.iter().any(|other| other.id == message.id))
        );
        request.before = second.next;
        let last = scan(&path, &request, &cancelled).await.unwrap();
        assert_eq!(last.messages.len(), 4);
        assert!(last.next.is_none());
        assert!(last.messages.iter().all(|message| message.id != 11));
        request.before = None;
        request.chats = Some(vec![43]);
        assert_eq!(
            scan(&path, &request, &cancelled)
                .await
                .unwrap()
                .messages
                .len(),
            1
        );
        let context = store.context(42, 50).await.unwrap();
        assert!(context.iter().any(|message| message.id == 49));
        assert!(context.iter().any(|message| message.id == 51));
        store
            .apply(&[NetworkEvent::MessagesDeleted {
                channel_id: None,
                message_ids: vec![50],
            }])
            .await
            .unwrap();
        assert!(store.context(42, 50).await.is_err());
        request.pattern = "(".to_owned();
        assert!(scan(&path, &request, &cancelled).await.is_err());
        request.pattern = "error".to_owned();
        cancelled.store(true, Ordering::Relaxed);
        assert!(scan(&path, &request, &cancelled).await.is_err());
        drop(store);
        std::fs::remove_dir_all(dir).unwrap();
    }
}

//! Cloud search arguments are separate from the verbatim local regex syntax.
use anyhow::{Result, ensure};
use chrono::NaiveDate;
use clap::{Parser, ValueEnum};

use crate::model::{ChatId, Message};

pub const PAGE_SIZE: usize = 100;

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum Sender {
    Me,
    Username(String),
    Id(ChatId),
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, ValueEnum)]
pub enum Media {
    #[default]
    All,
    Photo,
    Video,
    File,
    Music,
    Voice,
    Round,
    Gif,
    Link,
    Poll,
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct Filters {
    pub sender: Option<Sender>,
    pub after: Option<NaiveDate>,
    pub before: Option<NaiveDate>,
    pub media: Media,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Request {
    pub id: u64,
    pub chat_id: ChatId,
    pub query: String,
    pub filters: Filters,
    pub before_id: i32,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct Page {
    pub messages: Vec<Message>,
    pub next: Option<i32>,
    pub total: usize,
    /// Resolve a username once, then retain this identity while paging.
    pub sender: Option<ChatId>,
}

#[derive(Parser)]
#[command(
    name = ":search --cloud",
    disable_help_flag = true,
    disable_version_flag = true
)]
struct Arguments {
    #[arg(long, value_parser = parse_sender, value_name = "me|@username|ID", allow_negative_numbers = true)]
    from: Option<Sender>,
    #[arg(long, value_parser = parse_date, value_name = "YYYY-MM-DD")]
    after: Option<NaiveDate>,
    #[arg(long, value_parser = parse_date, value_name = "YYYY-MM-DD")]
    before: Option<NaiveDate>,
    #[arg(long, value_enum, default_value = "all")]
    media: Media,
    #[arg(trailing_var_arg = true)]
    text: Vec<String>,
}

/// Parse only the arguments after `--cloud`; never interpret a local regex.
/// # Errors
/// Returns invalid quoting, option, sender or date errors for the command UI.
pub fn parse(value: &str) -> Result<(String, Filters)> {
    #[cfg(unix)]
    let words = yazi_shared::shell::unix::split(value, false)?.0;
    #[cfg(windows)]
    let words = yazi_shared::shell::windows::split(&format!("search {value}"))?
        .into_iter()
        .skip(1)
        .collect::<Vec<_>>();
    let args = Arguments::try_parse_from(std::iter::once("search".to_owned()).chain(words))?;
    ensure!(
        !matches!((args.after, args.before), (Some(after), Some(before)) if after >= before),
        "--after must be earlier than --before (UTC)"
    );
    let query = args.text.join(" ");
    ensure!(query.len() <= 4096, "Search text is longer than 4096 bytes");
    Ok((
        query,
        Filters {
            sender: args.from,
            after: args.after,
            before: args.before,
            media: args.media,
        },
    ))
}

fn parse_sender(value: &str) -> Result<Sender, String> {
    if value == "me" {
        Ok(Sender::Me)
    } else if let Some(name) = value.strip_prefix('@').filter(|name| {
        !name.is_empty() && name.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_')
    }) {
        Ok(Sender::Username(name.to_owned()))
    } else if let Ok(id) = value.parse::<ChatId>()
        && id != 0
    {
        Ok(Sender::Id(id))
    } else {
        Err("Use me, @username, or a known Telegram peer ID".to_owned())
    }
}

fn parse_date(value: &str) -> Result<NaiveDate, String> {
    let date = NaiveDate::parse_from_str(value, "%Y-%m-%d")
        .map_err(|_| "Use a date in YYYY-MM-DD format".to_owned())?;
    let timestamp = date
        .and_hms_opt(0, 0, 0)
        .expect("midnight")
        .and_utc()
        .timestamp();
    if date.format("%Y-%m-%d").to_string() != value
        || !(1..=i64::from(i32::MAX)).contains(&timestamp)
    {
        return Err("Date must be YYYY-MM-DD between 1970-01-02 and 2038-01-19".to_owned());
    }
    Ok(date)
}

impl Filters {
    #[must_use]
    pub fn label(&self) -> String {
        let mut labels = Vec::new();
        if let Some(sender) = &self.sender {
            labels.push(match sender {
                Sender::Me => "from me".to_owned(),
                Sender::Username(name) => format!("from @{name}"),
                Sender::Id(id) => format!("from {id}"),
            });
        }
        if let Some(date) = self.after {
            labels.push(format!("after {date} UTC"));
        }
        if let Some(date) = self.before {
            labels.push(format!("before {date} UTC"));
        }
        if self.media != Media::All
            && let Some(value) = self.media.to_possible_value()
        {
            labels.push(value.get_name().to_owned());
        }
        labels.join(" · ")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cloud_arguments_preserve_quoted_text_and_validate_filters() {
        let (text, filters) = parse("--from @ada --after 2026-09-01 --before 2026-09-20 --media file \"release notes\" 中文").unwrap();
        assert_eq!(text, "release notes 中文");
        assert_eq!(filters.sender, Some(Sender::Username("ada".to_owned())));
        assert_eq!(filters.media, Media::File);
        assert!(filters.label().contains("after 2026-09-01 UTC"));
        assert_eq!(parse("-- --from literal").unwrap().0, "--from literal");
        assert_eq!(
            parse("--from -1001234567890").unwrap().1.sender,
            Some(Sender::Id(-1_001_234_567_890))
        );
        assert_eq!(parse("word --media photo").unwrap().0, "word --media photo");
        assert!(parse("--from me --media poll").unwrap().0.is_empty());
        for bad in [
            "--from nobody",
            "--from 0",
            "--media invalid",
            "--after 2026-02-30",
            "--after 2026-9-01",
            "--after 2038-01-20",
            "--before 1970-01-01",
            "--after 2026-09-20 --before 2026-09-01",
            "--unknown",
        ] {
            assert!(parse(bad).is_err(), "{bad}");
        }
    }
}

//! Bounded searches use the SDK iterator and the coordinator's single update stream.
use anyhow::{Context, Result, ensure};
use grammers_client::{Client, message::Message, tl::enums::MessagesFilter};
use grammers_session::types::PeerRef;

use crate::cloud_search::{Media, PAGE_SIZE, Request, Sender};

pub(super) struct Page {
    pub messages: Vec<Message>,
    pub next: Option<i32>,
    pub total: usize,
    pub sender: Option<PeerRef>,
}

pub(super) async fn search(
    client: &Client,
    peer: PeerRef,
    request: &Request,
    known_sender: Option<PeerRef>,
) -> Result<Page> {
    ensure!(
        request.query.len() <= 4096,
        "Search text is longer than 4096 bytes"
    );
    let mut iter = client
        .search_messages(peer)
        .query(&request.query)
        .filter(filter(request.filters.media))
        .offset_id(request.before_id)
        .limit(PAGE_SIZE + 1);
    let sender = match &request.filters.sender {
        Some(Sender::Me) => {
            iter = iter.sent_by_self();
            None
        }
        Some(Sender::Username(name)) => {
            let sender = client
                .resolve_username(name)
                .await?
                .context("Sender username was not found")?
                .to_ref()
                .await
                .map_err(anyhow::Error::from_boxed)?
                .context("Sender cannot be addressed")?;
            iter = iter.sent_by(sender);
            Some(sender)
        }
        Some(Sender::Id(id)) => {
            let sender = known_sender
                .filter(|peer| peer.id.bot_api_dialog_id() == Some(*id))
                .context("Sender ID is not known; use @username or me")?;
            iter = iter.sent_by(sender);
            Some(sender)
        }
        None => None,
    };
    if let Some(date) = request.filters.after {
        iter = iter.min_date(
            &date
                .and_hms_opt(0, 0, 0)
                .expect("midnight")
                .and_utc()
                .fixed_offset(),
        );
    }
    if let Some(date) = request.filters.before {
        iter = iter.max_date(
            &date
                .and_hms_opt(0, 0, 0)
                .expect("midnight")
                .and_utc()
                .fixed_offset(),
        );
    }
    let mut messages = Vec::new();
    while let Some(message) = iter.next().await? {
        ensure!(
            message.peer_id() == peer.id,
            "Search returned a message from another chat"
        );
        messages.push(message);
    }
    let total = iter.total().await?;
    let more = messages.len() > PAGE_SIZE;
    messages.truncate(PAGE_SIZE);
    let next = more.then(|| messages.last().expect("full page").id());
    Ok(Page {
        messages,
        next,
        total,
        sender,
    })
}

pub(super) async fn context(client: &Client, peer: PeerRef, id: i32) -> Result<Vec<Message>> {
    let target = super::message_actions::fetch(client, peer, id).await?;
    let mut iter = client
        .iter_messages(peer)
        .offset_id(id)
        .limit(super::HISTORY_LIMIT - 1);
    let mut messages = vec![target];
    while let Some(message) = iter.next().await? {
        ensure!(
            message.peer_id() == peer.id,
            "History returned a message from another chat"
        );
        messages.push(message);
    }
    messages.reverse();
    Ok(messages)
}

pub(super) async fn mentions(client: &Client, peer: PeerRef, before_id: i32) -> Result<Page> {
    let mut iter = client
        .unread_mentions(peer)
        .offset_id(before_id)
        .limit(PAGE_SIZE + 1);
    let mut messages = Vec::new();
    while let Some(message) = iter.next().await? {
        ensure!(
            message.peer_id() == peer.id,
            "Mention search returned another chat"
        );
        messages.push(message);
    }
    let total = iter.total().await?;
    let more = messages.len() > PAGE_SIZE;
    messages.truncate(PAGE_SIZE);
    Ok(Page {
        next: more.then(|| messages.last().expect("full page").id()),
        messages,
        total,
        sender: None,
    })
}

fn filter(media: Media) -> MessagesFilter {
    match media {
        Media::All => MessagesFilter::InputMessagesFilterEmpty,
        Media::Photo => MessagesFilter::InputMessagesFilterPhotos,
        Media::Video => MessagesFilter::InputMessagesFilterVideo,
        Media::File => MessagesFilter::InputMessagesFilterDocument,
        Media::Music => MessagesFilter::InputMessagesFilterMusic,
        Media::Voice => MessagesFilter::InputMessagesFilterVoice,
        Media::Round => MessagesFilter::InputMessagesFilterRoundVideo,
        Media::Gif => MessagesFilter::InputMessagesFilterGif,
        Media::Link => MessagesFilter::InputMessagesFilterUrl,
        Media::Poll => MessagesFilter::InputMessagesFilterPoll,
    }
}

use super::{App, Focus, KeyAction, Mode, TelegramCommand, TextInput};
use crate::{
    cloud_search,
    event::{ConnectionStatus, NetworkEvent},
    model::{ChatId, Message},
    search::{Cursor as LocalCursor, Request},
};

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum Scope {
    #[default]
    Chat,
    Folder,
    Account,
}

#[derive(Clone, Copy)]
enum Cursor {
    Local(LocalCursor),
    Cloud(i32),
}

#[derive(Clone, Default)]
pub enum Source {
    #[default]
    Local,
    Mentions(ChatId),
    Cloud {
        chat_id: ChatId,
        filters: cloud_search::Filters,
        sender: Option<ChatId>,
    },
}

#[derive(Clone)]
pub enum Results {
    Local(crate::search::Page),
    Cloud(cloud_search::Page),
}

impl Results {
    pub fn messages(&self) -> &[Message] {
        match self {
            Self::Local(page) => &page.messages,
            Self::Cloud(page) => &page.messages,
        }
    }
    pub(super) fn messages_mut(&mut self) -> &mut Vec<Message> {
        match self {
            Self::Local(page) => &mut page.messages,
            Self::Cloud(page) => &mut page.messages,
        }
    }
    fn next(&self) -> Option<Cursor> {
        match self {
            Self::Local(page) => page.next.map(Cursor::Local),
            Self::Cloud(page) => page.next.map(Cursor::Cloud),
        }
    }
}

#[derive(Clone, Default)]
pub struct State {
    pub query: TextInput,
    pub editing: bool,
    pub scope: Scope,
    pub scope_label: String,
    pub source: Source,
    pub page: Option<Results>,
    pub selected: usize,
    pub loading: bool,
    pub error: Option<String>,
    pub page_number: usize,
    request_id: u64,
    chats: Option<Vec<ChatId>>,
    starts: Vec<Option<Cursor>>,
    target: Option<(ChatId, i32)>,
}

impl State {
    pub fn is_cloud(&self) -> bool {
        !matches!(self.source, Source::Local)
    }

    pub fn is_mentions(&self) -> bool {
        matches!(self.source, Source::Mentions(_))
    }
}

impl App {
    pub(super) fn focused_mentions(&mut self) -> Vec<TelegramCommand> {
        if self.screen != super::Screen::Main || self.mode != Mode::Navigate {
            return Vec::new();
        }
        let id = if self.focus == Focus::Chats {
            self.selected_chat_entry().map(|chat| chat.id)
        } else {
            self.active_chat_id
        };
        id.map_or_else(Vec::new, |id| self.start_mentions(id))
    }

    pub(super) fn start_mentions(&mut self, chat_id: ChatId) -> Vec<TelegramCommand> {
        self.search.source = Source::Mentions(chat_id);
        self.search.query.clear();
        self.mode = Mode::Search;
        self.search_submit(None, true)
    }

    pub(super) fn start_cloud_search(
        &mut self,
        chat_id: ChatId,
        query: String,
        filters: cloud_search::Filters,
    ) -> Vec<TelegramCommand> {
        self.search.request_id = self.search.request_id.wrapping_add(1);
        self.search.source = Source::Cloud {
            chat_id,
            filters,
            sender: None,
        };
        self.search.query.set_value(query);
        self.search.page = None;
        self.search.target = None;
        self.search.loading = false;
        self.search.error = None;
        self.search.editing = true;
        self.mode = Mode::Search;
        self.update_search_scope();
        if self.search.query.is_empty() {
            vec![TelegramCommand::CancelSearch]
        } else {
            self.search_submit(None, true)
        }
    }

    pub(super) fn start_local_search(&mut self, query: Option<&str>) -> Vec<TelegramCommand> {
        if self.search.is_cloud() {
            self.search.source = Source::Local;
            self.search.query.clear();
            self.search.page = None;
        }
        self.open_search();
        self.search.editing = true;
        if let Some(query) = query.filter(|query| !query.is_empty()) {
            self.search.query.set_value(query);
            self.search_submit(None, true)
        } else {
            self.search_edited()
        }
    }

    pub(super) fn open_search(&mut self) -> Vec<TelegramCommand> {
        if self.search.query.is_empty() && !self.search.is_mentions() {
            self.search.editing = true;
            self.search.scope = if self.active_chat_id.is_some() {
                Scope::Chat
            } else {
                Scope::Folder
            };
        }
        self.mode = Mode::Search;
        if self.search.page.is_none() {
            self.search.editing = !self.search.is_mentions();
            self.update_search_scope();
        }
        Vec::new()
    }

    fn update_search_scope(&mut self) {
        if let Source::Cloud { chat_id, .. } | Source::Mentions(chat_id) = &self.search.source {
            self.search.scope_label = self
                .chats
                .iter()
                .find(|chat| chat.id == *chat_id)
                .map_or_else(|| format!("Chat {chat_id}"), |chat| chat.title.clone());
            return;
        }
        (self.search.chats, self.search.scope_label) = match self.search.scope {
            Scope::Chat => (
                Some(self.active_chat_id.into_iter().collect()),
                self.active_chat().map_or_else(
                    || "No open chat".to_owned(),
                    |chat| format!("Chat: {}", chat.title),
                ),
            ),
            Scope::Folder => {
                let folder = self
                    .folders
                    .iter()
                    .find(|folder| folder.id == self.folder_id);
                (
                    Some(
                        self.chats
                            .iter()
                            .filter(|chat| {
                                folder.is_none_or(|folder| {
                                    folder.contains(chat, chrono::Utc::now().timestamp())
                                })
                            })
                            .map(|chat| chat.id)
                            .collect(),
                    ),
                    format!(
                        "Folder: {}",
                        folder.map_or("All chats", |folder| folder.title.as_str())
                    ),
                )
            }
            Scope::Account => (None, "This account".to_owned()),
        };
    }

    pub(super) fn search_binding(
        &mut self,
        action: &str,
        count: usize,
    ) -> Option<Vec<TelegramCommand>> {
        match action {
            "cancel" => {
                self.mode = Mode::Navigate;
                self.search.loading = false;
                self.search.request_id = self.search.request_id.wrapping_add(1);
                Some(vec![TelegramCommand::CancelSearch])
            }
            "open" if self.search.loading => Some(Vec::new()),
            "open"
                if self.search.editing
                    || (self.search.is_mentions() && self.search.page.is_none()) =>
            {
                Some(self.search_submit(None, true))
            }
            "refresh" => Some(self.search_submit(None, true)),
            "open" => self.open_search_result(),
            "search_scope" if self.search.is_cloud() => Some(Vec::new()),
            "search_scope" => {
                self.search.scope = match self.search.scope {
                    Scope::Chat => Scope::Folder,
                    Scope::Folder => Scope::Account,
                    Scope::Account => Scope::Chat,
                };
                self.update_search_scope();
                self.search.page = None;
                self.search.editing = true;
                self.search.loading = false;
                self.search.request_id = self.search.request_id.wrapping_add(1);
                Some(vec![TelegramCommand::CancelSearch])
            }
            "search_query" if self.search.is_mentions() => Some(Vec::new()),
            "search_query" => {
                self.search.editing = true;
                Some(Vec::new())
            }
            "search_more" if !self.search.loading => {
                if let Some(next) = self.search.page.as_ref().and_then(Results::next) {
                    self.search.starts.push(Some(next));
                    self.search.page_number += 1;
                    Some(self.search_submit(Some(next), false))
                } else {
                    Some(Vec::new())
                }
            }
            "search_previous" if !self.search.loading && self.search.page_number > 1 => {
                self.search.starts.pop();
                self.search.page_number -= 1;
                Some(self.search_submit(self.search.starts.last().copied().flatten(), false))
            }
            "up" | "down" | "page_up" | "page_down" => {
                let length = self
                    .search
                    .page
                    .as_ref()
                    .map_or(0, |page| page.messages().len());
                if length > 0 {
                    self.search.editing = false;
                    let amount = if action.starts_with("page_") {
                        count.saturating_mul(10)
                    } else {
                        count
                    };
                    self.search.selected = if action.ends_with("up") {
                        self.search.selected.saturating_sub(amount)
                    } else {
                        self.search.selected.saturating_add(amount).min(length - 1)
                    };
                }
                Some(Vec::new())
            }
            _ => None,
        }
    }

    fn open_search_result(&mut self) -> Option<Vec<TelegramCommand>> {
        let message = self
            .search
            .page
            .as_ref()?
            .messages()
            .get(self.search.selected)?;
        let (chat_id, message_id) = (message.chat_id, message.id);
        if self.search.is_cloud() && self.connection != ConnectionStatus::Online {
            self.search.error = Some("Connect to Telegram to open this cloud result".to_owned());
            return Some(Vec::new());
        }
        self.search.request_id = self.search.request_id.wrapping_add(1);
        let request_id = self.search.request_id;
        self.search.loading = true;
        self.search.error = None;
        self.search.target = Some((chat_id, message_id));
        Some(vec![if self.search.is_cloud() {
            TelegramCommand::LoadCloudContext {
                chat_id,
                message_id,
                request_id,
            }
        } else {
            TelegramCommand::LoadCachedContext {
                chat_id,
                message_id,
                request_id,
            }
        }])
    }

    fn search_submit(&mut self, before: Option<Cursor>, fresh: bool) -> Vec<TelegramCommand> {
        self.search.request_id = self.search.request_id.wrapping_add(1);
        if fresh {
            self.search.starts = vec![None];
            self.search.page_number = 1;
            self.search.page = None;
            self.update_search_scope();
        }
        self.search.selected = 0;
        self.search.loading = true;
        self.search.editing = false;
        self.search.error = None;
        self.search.target = None;
        self.search.page = None;
        if self.search.is_cloud() && self.connection != ConnectionStatus::Online {
            self.search.loading = false;
            self.search.editing = !self.search.is_mentions();
            self.search.error = Some(
                "Connect to Telegram for cloud search and mentions; :search uses the offline cache"
                    .to_owned(),
            );
            return vec![TelegramCommand::CancelSearch];
        }
        match &self.search.source {
            Source::Mentions(chat_id) => vec![TelegramCommand::SearchMentions {
                chat_id: *chat_id,
                request_id: self.search.request_id,
                before_id: match before {
                    Some(Cursor::Cloud(id)) => id,
                    _ => 0,
                },
            }],
            Source::Cloud {
                chat_id,
                filters,
                sender,
            } => {
                let mut filters = filters.clone();
                if let Some(id) = sender {
                    filters.sender = Some(cloud_search::Sender::Id(*id));
                }
                vec![TelegramCommand::SearchCloud(cloud_search::Request {
                    id: self.search.request_id,
                    chat_id: *chat_id,
                    query: self.search.query.value().to_owned(),
                    filters,
                    before_id: match before {
                        Some(Cursor::Cloud(id)) => id,
                        _ => 0,
                    },
                })]
            }
            Source::Local => vec![TelegramCommand::SearchCached(Request {
                id: self.search.request_id,
                pattern: self.search.query.value().to_owned(),
                chats: self.search.chats.clone(),
                before: match before {
                    Some(Cursor::Local(cursor)) => Some(cursor),
                    _ => None,
                },
            })],
        }
    }

    pub(super) fn edit_search(&mut self, action: KeyAction) -> Vec<TelegramCommand> {
        if !self.search.editing {
            return Vec::new();
        }
        let before = self.search.query.value().to_owned();
        let query = &mut self.search.query;
        match action {
            KeyAction::Character(c) => query.insert(c),
            KeyAction::Backspace => _ = query.backspace(),
            KeyAction::Delete => _ = query.delete(),
            KeyAction::Left => _ = query.move_left(),
            KeyAction::Right => _ = query.move_right(),
            KeyAction::Home => query.move_home(),
            KeyAction::End => query.move_end(),
            KeyAction::Clear => query.clear(),
            KeyAction::DeleteWord => _ = query.delete_word_before(),
            _ => {}
        }
        if before == query.value() {
            Vec::new()
        } else {
            self.search_edited()
        }
    }

    pub(super) fn search_edited(&mut self) -> Vec<TelegramCommand> {
        self.search.page = None;
        self.search.error = None;
        self.search.loading = false;
        self.search.request_id = self.search.request_id.wrapping_add(1);
        vec![TelegramCommand::CancelSearch]
    }

    pub(super) fn finish_search(&mut self, request_id: u64, result: Result<Results, String>) {
        if self.search.request_id != request_id || self.mode != Mode::Search {
            return;
        }
        self.search.loading = false;
        match result {
            Ok(mut page) => {
                if self.search.is_mentions() {
                    page.messages_mut().retain(|message| {
                        message
                            .mention
                            .as_ref()
                            .is_some_and(|mention| mention.unread)
                    });
                }
                if let (Source::Cloud { sender, .. }, Results::Cloud(page)) =
                    (&mut self.search.source, &page)
                {
                    *sender = page.sender;
                }
                self.search.page = Some(page);
                self.search.error = None;
            }
            Err(error) => {
                self.search.error = Some(crate::model::sanitize_terminal_text(&error));
                self.search.editing = !self.search.is_mentions();
            }
        }
    }

    pub(super) fn open_search_context(
        &mut self,
        request_id: u64,
        chat_id: ChatId,
        message_id: i32,
        messages: Vec<Message>,
    ) {
        if self.search.request_id != request_id || self.mode != Mode::Search {
            return;
        }
        if self.search.target != Some((chat_id, message_id)) {
            return;
        }
        self.search.loading = false;
        self.search.target = None;
        if !messages
            .iter()
            .any(|message| message.id == message_id && message.chat_id == chat_id)
        {
            self.search.error =
                Some("Search result is no longer available; run the search again".to_owned());
            return;
        }
        self.mode = Mode::Navigate;
        self.clear_unread_navigation();
        self.focus = Focus::Conversation;
        self.narrow_conversation = true;
        self.active_history_request = None;
        self.older_motion = None;
        self.loading_history = false;
        self.active_chat_id = Some(chat_id);
        self.history_target_message = None;
        self.merge_history(chat_id, messages, None);
        self.browsing_older = true;
        self.new_messages_while_scrolled = 0;
        self.new_messages_to_anchor = 0;
        self.select_message_id(message_id, true);
        self.message_scroll = self.message_scroll.max(1);
        self.status_message = Some(format!(
            "{} · {} latest · {} results",
            if self.search.is_mentions() {
                "Mention"
            } else if self.search.is_cloud() {
                "Cloud search result"
            } else {
                "Cached search result"
            },
            self.keymap
                .hint(crate::keymap::Context::Conversation, "latest"),
            self.keymap
                .hint(crate::keymap::Context::Conversation, "search")
        ));
    }

    pub(super) fn observe_search(&mut self, event: &NetworkEvent) {
        if let NetworkEvent::CacheInvalidated { chat_id } = event {
            let affected = match &self.search.source {
                Source::Cloud { chat_id: id, .. } | Source::Mentions(id) => {
                    chat_id.is_none_or(|chat| chat == *id)
                }
                Source::Local => chat_id.is_none_or(|chat| {
                    self.search
                        .chats
                        .as_ref()
                        .is_none_or(|chats| chats.contains(&chat))
                }),
            };
            if affected {
                self.search.request_id = self.search.request_id.wrapping_add(1);
                self.search.loading = false;
                self.search.page = None;
                self.search.target = None;
                self.search.editing = !self.search.is_mentions();
                self.search.error = Some("History is resyncing; run the search again".to_owned());
            }
        }
        let mentions = self.search.is_mentions();
        let Some(page) = self.search.page.as_mut() else {
            return;
        };
        match event {
            NetworkEvent::MessageUpdated(message) | NetworkEvent::NewMessage(message) => {
                if let Some(current) = page
                    .messages_mut()
                    .iter_mut()
                    .find(|current| current.chat_id == message.chat_id && current.id == message.id)
                {
                    *current = message.clone();
                    super::sanitize_message(current);
                }
            }
            NetworkEvent::MessageContentsRead {
                channel_id,
                message_ids,
            } => {
                for message in page.messages_mut() {
                    message.acknowledge_contents(*channel_id, message_ids);
                }
            }
            NetworkEvent::MessagesDeleted {
                channel_id,
                message_ids,
            } => {
                page.messages_mut().retain(|message| {
                    let affected = channel_id.map_or(message.chat_id > -1_000_000_000_000, |id| {
                        message.chat_id == id
                    });
                    !affected || !message_ids.contains(&message.id)
                });
                self.search.selected = self
                    .search
                    .selected
                    .min(page.messages().len().saturating_sub(1));
            }
            _ => {}
        }
        if mentions {
            page.messages_mut().retain(|message| {
                message
                    .mention
                    .as_ref()
                    .is_some_and(|mention| mention.unread)
            });
            self.search.selected = self
                .search
                .selected
                .min(page.messages().len().saturating_sub(1));
        }
    }
}

use super::{
    AppState, Clear, Constraint, DANGER, Frame, Layout, List, ListItem, ListState, Local, MUTED,
    Modifier, Paragraph, Position, Rect, Style, Wrap, centered, clamp_u16, pane_block, spinner,
    truncate_cells, wrapped_height,
};
use crate::app::search::{Results, Source};
use crate::keymap::Context;

pub(super) fn render_search(frame: &mut Frame<'_>, area: Rect, app: &AppState) {
    let popup = centered(
        area,
        area.width.min(110),
        area.height.saturating_sub(2).max(8),
    );
    frame.render_widget(Clear, popup);
    let source = if app.search.is_mentions() {
        "Unread mentions"
    } else if app.search.is_cloud() {
        "Telegram search"
    } else {
        "Local regex"
    };
    let block = pane_block(format!(" {source} · {} ", app.search.scope_label), true);
    let inner = block.inner(popup);
    frame.render_widget(block, popup);
    let coverage = coverage_label(app);
    let rows = Layout::vertical([
        Constraint::Length(if app.search.is_mentions() { 0 } else { 3 }),
        Constraint::Length(wrapped_height(&coverage, inner.width).clamp(2, 4)),
        Constraint::Min(1),
        Constraint::Length(3),
    ])
    .split(inner);
    let input = &app.search.query;
    let scroll = input
        .cursor_display_width()
        .saturating_sub(usize::from(rows[0].width.saturating_sub(3)));
    if !app.search.is_mentions() {
        frame.render_widget(
            Paragraph::new(input.value())
                .scroll((0, clamp_u16(scroll)))
                .block(pane_block(
                    if app.search.is_cloud() {
                        " Text "
                    } else {
                        " Pattern "
                    }
                    .to_owned(),
                    app.search.editing,
                )),
            rows[0],
        );
    }
    if app.search.editing {
        frame.set_cursor_position(Position::new(
            rows[0].x + 1 + clamp_u16(input.cursor_display_width().saturating_sub(scroll)),
            rows[0].y + 1,
        ));
    }
    frame.render_widget(
        Paragraph::new(coverage)
            .wrap(Wrap { trim: true })
            .style(Style::default().fg(if app.search.error.is_some() {
                DANGER
            } else {
                MUTED
            })),
        rows[1],
    );
    let height = usize::from(rows[2].height).max(1);
    let start = app.search.selected.saturating_add(1).saturating_sub(height);
    let messages = app.search.page.as_ref().map_or(&[][..], Results::messages);
    let items: Vec<_> = messages
        .iter()
        .skip(start)
        .take(height)
        .map(|message| result_row(message, app, usize::from(rows[2].width.saturating_sub(2))))
        .collect();
    let items = if items.is_empty() && app.search.page.is_some() && !app.search.loading {
        vec![ListItem::new(if app.search.is_mentions() {
            "No unread mentions"
        } else if app.search.is_cloud() {
            "No Telegram matches"
        } else {
            "No matches in the cached range"
        })]
    } else {
        items
    };
    let mut state = ListState::default()
        .with_selected((!messages.is_empty()).then_some(app.search.selected.saturating_sub(start)));
    frame.render_stateful_widget(
        List::new(items)
            .highlight_symbol("› ")
            .highlight_style(Style::default().add_modifier(Modifier::REVERSED)),
        rows[2],
        &mut state,
    );
    render_hints(frame, rows[3], app);
}

fn render_hints(frame: &mut Frame<'_>, area: Rect, app: &AppState) {
    let hint = |action| app.keymap.hint(Context::Search, action);
    if app.search.is_mentions() {
        frame.render_widget(
            Paragraph::new(format!(
                "{} open · {} close\n{} refresh\n{} previous · {} next",
                hint("open"),
                hint("cancel"),
                hint("refresh"),
                hint("search_previous"),
                hint("search_more"),
            ))
            .style(Style::default().fg(MUTED)),
            area,
        );
        return;
    }
    frame.render_widget(
        Paragraph::new(format!(
            "{} {} · {} close\n{} · {} edit\n{} previous · {} next",
            hint("open"),
            if app.search.editing { "search" } else { "open" },
            hint("cancel"),
            if app.search.is_cloud() {
                ":search --cloud to change filters".to_owned()
            } else {
                format!("{} scope", hint("search_scope"))
            },
            hint("search_query"),
            hint("search_previous"),
            hint("search_more")
        ))
        .style(Style::default().fg(MUTED)),
        area,
    );
}

fn coverage_label(app: &AppState) -> String {
    if let Some(error) = &app.search.error {
        error.clone()
    } else if app.search.loading {
        format!(
            "{} {}…",
            spinner(app.tick),
            if app.search.is_cloud() {
                "Loading from Telegram"
            } else {
                "Searching cached messages"
            }
        )
    } else if let Some(Results::Local(page)) = &app.search.page {
        let date = |time: Option<i64>| {
            time.and_then(|time| chrono::DateTime::from_timestamp(time, 0))
                .map_or_else(
                    || "—".to_owned(),
                    |date| date.format("%Y-%m-%d").to_string(),
                )
        };
        format!(
            "{} cached messages · {} to {} UTC · page {} · {} hits{}",
            page.cached_messages,
            date(page.oldest),
            date(page.newest),
            app.search.page_number,
            page.messages.len(),
            if page.next.is_some() {
                " · more available"
            } else {
                ""
            }
        )
    } else if app.search.is_mentions() {
        app.search.page.as_ref().map_or_else(
            || "Mentions and replies to you; refresh to load from Telegram.".to_owned(),
            |page| {
                let Results::Cloud(page) = page else {
                    unreachable!("mentions come from Telegram")
                };
                format!(
                    "{} unread at search · page {} · {} shown",
                    page.total,
                    app.search.page_number,
                    page.messages.len()
                )
            },
        )
    } else if let Source::Cloud { filters, .. } = &app.search.source {
        let coverage = if let Some(Results::Cloud(page)) = &app.search.page {
            format!(
                "Telegram: {} matches · page {} · {} hits{}",
                page.total,
                app.search.page_number,
                page.messages.len(),
                if page.next.is_some() {
                    " · more available"
                } else {
                    ""
                }
            )
        } else {
            "Searches this chat on Telegram; text uses Telegram's search syntax.".to_owned()
        };
        let filters = filters.label();
        if filters.is_empty() {
            coverage
        } else {
            format!("{coverage}\n{filters}")
        }
    } else {
        "Searches cached message text only; older uncached history is not included.".to_owned()
    }
}

fn result_row(message: &crate::model::Message, app: &AppState, width: usize) -> ListItem<'static> {
    let title = app
        .chats
        .iter()
        .find(|chat| chat.id == message.chat_id)
        .map_or("Unknown", |chat| chat.title.as_str());
    ListItem::new(truncate_cells(
        &format!(
            "{} · {} · {} · {}",
            title,
            crate::model::sanitize_terminal_line(&message.sender),
            message
                .timestamp
                .with_timezone(&Local)
                .format("%m-%d %H:%M"),
            crate::model::sanitize_terminal_line(&message.preview_text())
        ),
        width,
    ))
}
